//! Golden vectors for the standing v5 tables and transitions, generated by
//! tests/vectors/standing/standing_ref.py (integer-only oracle).
mod common;
use czkp::standing::{Params, Policy, Q, State};
use serde_json::Value;

fn golden() -> Value {
    serde_json::from_str(include_str!("vectors/standing/golden.json")).unwrap()
}

fn u(v: &Value) -> u64 {
    v.as_u64().unwrap()
}

fn list(v: &Value) -> Vec<u64> {
    v.as_array().unwrap().iter().map(u).collect()
}

fn params(v: &Value) -> Params {
    Params {
        c0: u(&v["c0"]),
        h_a: u(&v["h_A"]),
        h_g: u(&v["h_G"]),
        n_half: u(&v["n_half"]),
        n_c: u(&v["n_c"]),
        e_q: u(&v["e_q"]),
        r_max: u(&v["r_max"]),
        r_age: u(&v["r_age"]),
        c_max_q: u(&v["c_max_q"]),
        c_vet: u(&v["c_vet"]),
        age_vet: u(&v["age_vet"]),
        boost_q: u(&v["boost_q"]),
        boost_days: u(&v["boost_days"]),
        slope_q: u(&v["slope_q"]),
        mid_q: u(&v["mid_q"]),
        kappa_q: u(&v["kappa_q"]),
        loan_use_q: u(&v["loan_use_q"]),
        voucher: common::reference().voucher,
    }
}

fn state(v: &Value) -> State {
    State {
        g: u(&v["G"]),
        a: u(&v["A"]),
        c: u(&v["C"]),
        pr: u(&v["Pr"]),
        pg: u(&v["Pg"]),
        lc: u(&v["Lc"]),
        day: u(&v["day"]),
        joined: u(&v["joined"]),
    }
}

#[test]
fn defaults_match_the_oracle() {
    let g = golden();
    assert_eq!(params(&g["defaults_resolved"]), common::reference());
}

#[test]
fn tables_and_scripts_match_the_oracle() {
    let g = golden();
    for (name, set) in g["sets"].as_object().unwrap() {
        let policy = Policy::derive(params(&set["params"])).unwrap();
        assert_eq!(policy.factor, u(&set["factor"]), "{name} factor");
        assert_eq!(policy.trust.to_vec(), list(&set["trust"]), "{name} trust");
        assert_eq!(policy.g_table.to_vec(), list(&set["g_table"]), "{name} g");
        assert_eq!(policy.a_table.to_vec(), list(&set["a_table"]), "{name} a");
        // The oracle predates the voucher parameters, which follow the 18 head fields.
        assert_eq!(
            policy.fields().len(),
            u(&set["fields_len"]) as usize + czkp::standing::VOUCHER_FIELDS
        );
        for (script, steps) in set["scripts"].as_object().unwrap() {
            let mut st = State::new(0, u(&set["a0_q"]));
            for step in steps.as_array().unwrap() {
                let op = step["step"][0].as_str().unwrap();
                let arg = u(&step["step"][1]);
                match op {
                    "day" => st.advance(arg, &policy),
                    "recv" => st.answer_received(&policy),
                    "give" => st.answer_given(&policy),
                    "miss" => st.unanswered(&policy),
                    "credit" => st.group_credit(arg),
                    "punished" => st.punished(arg == 1),
                    "punish_given" => st.punish_given(),
                    other => panic!("unknown op {other}"),
                }
                assert_eq!(st, state(&step["state"]), "{name}/{script}/{op}");
                assert_eq!(st.cap(&policy), u(&step["cap"]), "{name}/{script}/{op} cap");
            }
        }
    }
}

#[test]
fn ranges_are_enforced() {
    let ok = common::reference();
    assert!(ok.validate().is_ok());
    let bad = [
        Params { n_half: 4, ..ok },
        Params { n_half: 201, ..ok },
        Params { c_max_q: Q, ..ok },
        Params {
            slope_q: Q - 1,
            ..ok
        },
        Params { mid_q: 0, ..ok },
        Params {
            kappa_q: 7 * Q,
            ..ok
        },
        Params { h_g: 0, ..ok },
        Params { h_a: 65, ..ok },
        Params {
            loan_use_q: 0,
            ..ok
        },
    ];
    for p in bad {
        assert!(Policy::derive(p).is_err(), "{p:?}");
    }
}

#[test]
fn digest_binds_every_parameter_and_table_entry() {
    let domain = [7; 32];
    let base = Policy::derive(common::reference()).unwrap();
    let digest = base.digest(&domain).unwrap();
    assert_eq!(digest, base.digest(&domain).unwrap());
    assert_ne!(digest, base.digest(&[8; 32]).unwrap());
    let other = Policy::derive(Params {
        n_half: 26,
        ..common::reference()
    })
    .unwrap();
    assert_ne!(digest, other.digest(&domain).unwrap());
    let mut tampered = base.clone();
    tampered.trust[30] += 1;
    assert_ne!(digest, tampered.digest(&domain).unwrap());
    let mut tampered = base.clone();
    tampered.a_table[3] += 1;
    assert_ne!(digest, tampered.digest(&domain).unwrap());
}

#[test]
fn behavior_properties() {
    let p = Policy::derive(common::reference()).unwrap();
    // Waiting does not heal: no calendar decay of punishments, only clean conversations.
    let mut st = State::new(0, 2 * Q);
    st.punished(false);
    st.punished(false);
    let before = (st.pr, st.pg);
    st.advance(10_000, &p);
    assert_eq!((st.pr, st.pg), before);
    // A clean conversation decays both memories, rounding up, never to zero.
    for _ in 0..2_000 {
        st.answer_given(&p);
    }
    assert!(st.pr >= 1);
    // The cap never falls below one.
    let mut worst = State::new(0, 0);
    for _ in 0..50 {
        worst.punished(false);
    }
    assert_eq!(worst.cap(&p), 1);
}

/// Pinned against the Noir circuit (cblc tests/standing-probe.mts, same value): the policy
/// digest of the default parameters under the account-state domain.
#[test]
fn default_digest_equals_the_noir_digest() {
    let mut domain = [0u8; 32];
    let tag = b"cfrm.account-state.v2";
    domain[32 - tag.len()..].copy_from_slice(tag);
    let digest = Policy::derive(common::reference())
        .unwrap()
        .digest(&domain)
        .unwrap();
    let expected = "13869f92e82373e15e5b9bbaf09bb0d2f4a71e7af912d20c68ae8ceb98710231";
    let got: String = digest.iter().map(|b| format!("{b:02x}")).collect();
    assert_eq!(got, expected);
}
/// Boundary products, not sums: the validate() ranges are exact multiples of Q.
/// Each assertion below fails if one bound is a sum instead of a product, a
/// quotient instead of a remainder, or a multiple instead of a divisor.
#[test]
fn validate_bounds_are_exact_products_of_q() {
    // boost_q range 0..=2*Q: 100_000 is inside the product, outside the sum 2+Q.
    assert!(
        Policy::derive(Params {
            boost_q: 100_000,
            ..common::reference()
        })
        .is_ok()
    );
    // mid_q range Q/4..=3*Q: 100_000 is inside the product, outside the sum 3+Q.
    assert!(
        Policy::derive(Params {
            mid_q: 100_000,
            ..common::reference()
        })
        .is_ok()
    );
    // kappa_q range Q/2..=6*Q: 0 is below the quotient but inside the remainder Q%2.
    assert!(
        Policy::derive(Params {
            kappa_q: 0,
            ..common::reference()
        })
        .is_err()
    );
    // The quotient boundary itself is accepted.
    assert!(
        Policy::derive(Params {
            kappa_q: Q / 2,
            ..common::reference()
        })
        .is_ok()
    );
}

/// The boost window is half-open: answering on the exact last day gets no boost.
#[test]
fn answer_boost_ends_on_the_exact_last_day() {
    let p = Policy::derive(common::reference()).unwrap();
    let mut st = State::new(0, 0);
    st.advance(p.params.boost_days, &p);
    st.answer_received(&p);
    assert_eq!(st.g, Q);
}

/// A member admitted after day zero still earns the boost inside the window:
/// the window measures days since joining, not the calendar day.
#[test]
fn answer_boost_counts_days_since_joining() {
    let p = Policy::derive(common::reference()).unwrap();
    let mut st = State::new(10, 0);
    st.advance(25, &p);
    st.answer_received(&p);
    assert_eq!(st.g, Q + p.params.boost_q);
}

/// The veteran offset divides the clean record by the full-veteran record:
/// a product would cap every member at the maximum after one clean record.
#[test]
fn veteran_divides_the_clean_record() {
    let p = Policy::derive(common::reference()).unwrap();
    // c/c_vet binds first (2184): the product c*c_vet would cap f at Q instead,
    // granting the full veteran offset and hiding 49_000 of excess punishment.
    let st = State {
        g: 0,
        a: 0,
        c: Q,
        pr: 49_000,
        pg: 0,
        lc: 0,
        day: 60,
        joined: 0,
    };
    assert!(st.trust(&p) < Q);
}

/// The veteran offset measures membership age, not the calendar day:
/// adding the admission day would grant a newcomer the full offset.
#[test]
fn veteran_counts_days_since_joining() {
    let p = Policy::derive(common::reference()).unwrap();
    let st = State {
        g: 0,
        a: 0,
        c: 60 * Q,
        pr: 49_000,
        pg: 0,
        lc: 0,
        day: 31,
        joined: 30,
    };
    assert!(st.trust(&p) < Q);
}

/// The reach ceiling grows with days since joining: a newcomer admitted late
/// does not inherit the calendar day as free seniority.
#[test]
fn reach_ceiling_counts_days_since_joining() {
    let p = Policy::derive(common::reference()).unwrap();
    let st = State {
        g: 100 * Q,
        a: 0,
        c: 0,
        pr: 0,
        pg: 0,
        lc: 0,
        day: 10,
        joined: 10,
    };
    assert_eq!(st.reach(&p), 2 << 16);
}
